//! Benchmarks for code generated by the `Payload` derive.
//!
//! Measures payload serialization and deserialization through the derived
//! implementations, to check that they add little or no overhead over
//! hand-written code.
//!
//! Run with:
//! ```bash
//! cargo bench --package orcher --features derive
//! ```

use criterion::{black_box, criterion_group, criterion_main, Criterion};
use orcher::prelude::*;
use serde::{Deserialize, Serialize};

// ============================================================================
// Test Types
// ============================================================================

#[derive(Payload, Serialize, Deserialize, Clone)]
struct BenchmarkData {
    id: String,
    value: i64,
    tags: Vec<String>,
    metadata: std::collections::HashMap<String, String>,
}

#[derive(Serialize, Deserialize, Clone)]
struct ManualData {
    id: String,
    value: i64,
    tags: Vec<String>,
    metadata: std::collections::HashMap<String, String>,
}

impl ManualData {
    fn to_payload_manual(&self) -> std::result::Result<orcher::Payload, orcher::Error> {
        orcher::Payload::from_json(self).map_err(|e| orcher::Error::Serialization(e.to_string()))
    }

    fn from_payload_manual(payload: &orcher::Payload) -> std::result::Result<Self, orcher::Error> {
        payload
            .to_json::<Self>()
            .map_err(|e| orcher::Error::Serialization(e.to_string()))
    }
}

// ============================================================================
// Benchmark: Payload Serialization
// ============================================================================

fn benchmark_payload_serialization(c: &mut Criterion) {
    let mut metadata = std::collections::HashMap::new();
    metadata.insert("key1".to_string(), "value1".to_string());
    metadata.insert("key2".to_string(), "value2".to_string());

    let derived_data = BenchmarkData {
        id: "bench-001".to_string(),
        value: 42,
        tags: vec!["tag1".to_string(), "tag2".to_string(), "tag3".to_string()],
        metadata: metadata.clone(),
    };

    let manual_data = ManualData {
        id: "bench-001".to_string(),
        value: 42,
        tags: vec!["tag1".to_string(), "tag2".to_string(), "tag3".to_string()],
        metadata,
    };

    c.bench_function("payload_derive_to_payload", |b| {
        b.iter(|| {
            let payload = black_box(&derived_data).to_payload().unwrap();
            black_box(payload);
        })
    });

    c.bench_function("payload_manual_to_payload", |b| {
        b.iter(|| {
            let payload = black_box(&manual_data).to_payload_manual().unwrap();
            black_box(payload);
        })
    });
}

// ============================================================================
// Benchmark: Payload Deserialization
// ============================================================================

fn benchmark_payload_deserialization(c: &mut Criterion) {
    let mut metadata = std::collections::HashMap::new();
    metadata.insert("key1".to_string(), "value1".to_string());
    metadata.insert("key2".to_string(), "value2".to_string());

    let data = BenchmarkData {
        id: "bench-001".to_string(),
        value: 42,
        tags: vec!["tag1".to_string(), "tag2".to_string(), "tag3".to_string()],
        metadata,
    };

    let payload = data.to_payload().unwrap();

    c.bench_function("payload_derive_from_payload", |b| {
        b.iter(|| {
            let decoded = BenchmarkData::from_payload(black_box(&payload)).unwrap();
            black_box(decoded);
        })
    });

    c.bench_function("payload_manual_from_payload", |b| {
        b.iter(|| {
            let decoded = ManualData::from_payload_manual(black_box(&payload)).unwrap();
            black_box(decoded);
        })
    });
}

// ============================================================================
// Benchmark: Round-Trip Serialization
// ============================================================================

fn benchmark_payload_roundtrip(c: &mut Criterion) {
    let mut metadata = std::collections::HashMap::new();
    metadata.insert("key1".to_string(), "value1".to_string());
    metadata.insert("key2".to_string(), "value2".to_string());

    let data = BenchmarkData {
        id: "bench-001".to_string(),
        value: 42,
        tags: vec!["tag1".to_string(), "tag2".to_string(), "tag3".to_string()],
        metadata,
    };

    c.bench_function("payload_derive_roundtrip", |b| {
        b.iter(|| {
            let payload = black_box(&data).to_payload().unwrap();
            let decoded = BenchmarkData::from_payload(&payload).unwrap();
            black_box(decoded);
        })
    });
}

// ============================================================================
// Benchmark: Small vs Large Payloads
// ============================================================================

fn benchmark_payload_sizes(c: &mut Criterion) {
    // Small payload
    let small_data = BenchmarkData {
        id: "s".to_string(),
        value: 1,
        tags: vec![],
        metadata: std::collections::HashMap::new(),
    };

    // Large payload
    let mut large_metadata = std::collections::HashMap::new();
    for i in 0..100 {
        large_metadata.insert(format!("key{}", i), format!("value{}", i));
    }

    let large_data = BenchmarkData {
        id: "large-bench-001-with-long-id".to_string(),
        value: 999999,
        tags: (0..50).map(|i| format!("tag{}", i)).collect(),
        metadata: large_metadata,
    };

    c.bench_function("payload_small_serialize", |b| {
        b.iter(|| {
            let payload = black_box(&small_data).to_payload().unwrap();
            black_box(payload);
        })
    });

    c.bench_function("payload_large_serialize", |b| {
        b.iter(|| {
            let payload = black_box(&large_data).to_payload().unwrap();
            black_box(payload);
        })
    });

    let small_payload = small_data.to_payload().unwrap();
    let large_payload = large_data.to_payload().unwrap();

    c.bench_function("payload_small_deserialize", |b| {
        b.iter(|| {
            let decoded = BenchmarkData::from_payload(black_box(&small_payload)).unwrap();
            black_box(decoded);
        })
    });

    c.bench_function("payload_large_deserialize", |b| {
        b.iter(|| {
            let decoded = BenchmarkData::from_payload(black_box(&large_payload)).unwrap();
            black_box(decoded);
        })
    });
}

// ============================================================================
// Benchmark: try_into_payload
// ============================================================================

fn benchmark_try_into_payload(c: &mut Criterion) {
    c.bench_function("payload_try_into", |b| {
        b.iter(|| {
            let data = BenchmarkData {
                id: "bench-001".to_string(),
                value: 42,
                tags: vec!["tag1".to_string()],
                metadata: std::collections::HashMap::new(),
            };
            let payload = black_box(data).try_into_payload().unwrap();
            black_box(payload);
        })
    });
}

// ============================================================================
// Benchmark: Multiple Payload Types
// ============================================================================

#[derive(Payload, Serialize, Deserialize, Clone)]
struct SimpleType {
    value: i32,
}

#[derive(Payload, Serialize, Deserialize, Clone)]
struct ComplexType {
    id: String,
    values: Vec<i32>,
    map: std::collections::HashMap<String, i32>,
}

fn benchmark_different_types(c: &mut Criterion) {
    let simple = SimpleType { value: 42 };
    let complex = ComplexType {
        id: "complex".to_string(),
        values: vec![1, 2, 3, 4, 5],
        map: {
            let mut m = std::collections::HashMap::new();
            m.insert("a".to_string(), 1);
            m.insert("b".to_string(), 2);
            m
        },
    };

    c.bench_function("payload_simple_type", |b| {
        b.iter(|| {
            let payload = black_box(&simple).to_payload().unwrap();
            let decoded = SimpleType::from_payload(&payload).unwrap();
            black_box(decoded);
        })
    });

    c.bench_function("payload_complex_type", |b| {
        b.iter(|| {
            let payload = black_box(&complex).to_payload().unwrap();
            let decoded = ComplexType::from_payload(&payload).unwrap();
            black_box(decoded);
        })
    });
}

// ============================================================================
// Benchmark Groups
// ============================================================================

criterion_group!(
    benches,
    benchmark_payload_serialization,
    benchmark_payload_deserialization,
    benchmark_payload_roundtrip,
    benchmark_payload_sizes,
    benchmark_try_into_payload,
    benchmark_different_types
);

criterion_main!(benches);
